// STUDIOSB6L trusted session resolver for Cloudflare Workers.
// Opaque 256-bit random tokens are generated by the authentication service.
// Store only SHA-256 token hashes in D1. Never log tokens or return them in errors.
import {authorize} from './authorization-policy.mjs';
import {requestSessionToken,hashSessionToken} from './session-tokens.mjs';
export async function resolveSession(request,env){
  if(!env?.DB)return null;
  const token=requestSessionToken(request);
  if(!token)return null;
  const hash=await hashSessionToken(token);
  try{
    const row=await env.DB.prepare('SELECT user_id, role, verified, mfa_verified, disabled, expires_at FROM sessions WHERE token_hash = ? LIMIT 1').bind(hash).first();
    if(!row||typeof row.expires_at!=='number'||!Number.isFinite(row.expires_at)||row.expires_at<=Date.now()||row.disabled===1||row.verified!==1)return null;
    return {userId:row.user_id,role:row.role,verified:row.verified===1,mfaVerified:row.mfa_verified===1,disabled:row.disabled===1,expiresAt:row.expires_at};
  }catch{return null}
}
export async function requireAuthenticatedCapability(request,env,capability){
  const session=await resolveSession(request,env);
  if(!authorize(session,capability))return {session:null,response:new Response(JSON.stringify({error:'Forbidden'}),{status:403,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}})};
  return {session,response:null};
}
